// ============================================================================
// File: tb/v3/tb_ch02_skid_buffer.v
// Module: tb_ch02_skid_buffer
// Description:
//   Cycle-accurate testbench for rtl/v3/ch02_skid_buffer.v:
//   - Reads cycle-by-cycle stimulus from tb_ch02_skid_stim.txt.
//   - Reads expected values from tb_ch02_skid_expected.txt generated by Python twin.
//   - Compares bit-for-bit and cycle-for-cycle:
//     * s_ready
//     * m_valid
//     * m_data (when m_valid is high)
//     * skid_valid (dut.skid_valid internal state)
//   - Fully compatible with `iverilog -g2012 -Wall`.
// ============================================================================

`timescale 1ns/1ps

module tb_ch02_skid_buffer;

    parameter DATA_WIDTH = 16;

    reg clk = 0;
    always #10 clk = ~clk; // 50 MHz (20 ns period)

    reg                  rst_n;
    reg                  s_valid;
    reg [DATA_WIDTH-1:0] s_data;
    wire                 s_ready;

    wire                 m_valid;
    wire [DATA_WIDTH-1:0] m_data;
    reg                  m_ready;

    // Instantiate DUT
    ch02_skid_buffer #(
        .DATA_WIDTH(DATA_WIDTH)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .s_valid(s_valid),
        .s_data(s_data),
        .s_ready(s_ready),
        .m_valid(m_valid),
        .m_data(m_data),
        .m_ready(m_ready)
    );

    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus line variables
    integer stim_rst_n;
    integer stim_s_vld;
    reg [DATA_WIDTH-1:0] stim_s_dat;
    integer stim_m_rdy;

    // Expected line variables
    integer exp_c;
    integer exp_rst_n;
    integer exp_s_vld;
    reg [DATA_WIDTH-1:0] exp_s_dat;
    integer exp_m_rdy;
    integer exp_s_rdy;
    integer exp_m_vld;
    reg [DATA_WIDTH-1:0] exp_m_dat;
    integer exp_sk_vld;

    initial begin
        rst_n = 0;
        s_valid = 0;
        s_data = {DATA_WIDTH{1'b0}};
        m_ready = 0;
        cycle_idx = 0;
        errors = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch02_skid_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch02_skid_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("ERROR: Cannot open tb_ch02_skid_stim.txt");
            $finish;
        end

        // Open expected trace file
        exp_fd = $fopen("verify_v3/tb_ch02_skid_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch02_skid_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("ERROR: Cannot open tb_ch02_skid_expected.txt");
            $finish;
        end

        $display("=== STARTING CH02 SKID BUFFER CYCLE-BY-CYCLE VERIFICATION ===");

        // Run cycle by cycle
        while ($fscanf(stim_fd, "%d %d %h %d\n", stim_rst_n, stim_s_vld, stim_s_dat, stim_m_rdy) == 4 &&
               $fscanf(exp_fd, "%d %d %d %h %d %d %d %h %d\n",
                       exp_c, exp_rst_n, exp_s_vld, exp_s_dat, exp_m_rdy,
                       exp_s_rdy, exp_m_vld, exp_m_dat, exp_sk_vld) == 9) begin

            // Drive inputs before posedge clk
            rst_n   <= (stim_rst_n != 0) ? 1'b1 : 1'b0;
            s_valid <= (stim_s_vld != 0) ? 1'b1 : 1'b0;
            s_data  <= stim_s_dat;
            m_ready <= (stim_m_rdy != 0) ? 1'b1 : 1'b0;

            // Wait for clock edge and delta settle
            @(posedge clk);
            #1;

            // Check outputs against expected
            if (s_ready !== ((exp_s_rdy != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: s_ready mismatch (got %b, exp %0d)",
                         cycle_idx, s_ready, exp_s_rdy);
                errors = errors + 1;
            end

            if (m_valid !== ((exp_m_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: m_valid mismatch (got %b, exp %0d)",
                         cycle_idx, m_valid, exp_m_vld);
                errors = errors + 1;
            end

            if (m_valid && (m_data !== exp_m_dat)) begin
                $display("[FAIL] Cycle %0d: m_data mismatch (got 0x%04x, exp 0x%04x)",
                         cycle_idx, m_data, exp_m_dat);
                errors = errors + 1;
            end

            if (dut.skid_valid !== ((exp_sk_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: skid_valid mismatch (got %b, exp %0d)",
                         cycle_idx, dut.skid_valid, exp_sk_vld);
                errors = errors + 1;
            end

            if (errors >= 20) begin
                $display("Too many errors. Aborting simulation.");
                $finish;
            end

            cycle_idx = cycle_idx + 1;
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("Simulation completed %0d cycles.", cycle_idx);
        $display("Total comparison errors: %0d", errors);

        if (errors == 0 && cycle_idx >= 200) begin
            $display("=== [PASS] CH02 SKID BUFFER MATCHED PYTHON TWIN BIT-FOR-BIT AND CYCLE-FOR-CYCLE ON %0d CYCLES ===", cycle_idx);
        end else begin
            $display("=== [FAIL] CH02 SKID BUFFER FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
